import { FC, HTMLAttributes } from 'react';
import { useTranslation } from 'react-i18next';

import cn from 'classnames';

import { CreateSourceForm } from 'entities/Source';
import { Page, PageTitle } from 'shared/ui';

import styles from './CreateSource.module.scss';

interface ICreateSourceProps extends HTMLAttributes<HTMLDivElement> {}

export const CreateSource: FC<ICreateSourceProps> = ({ className, ...props }) => {
	const { t } = useTranslation();

	return (
		<Page {...props} className={cn(className, styles.createSource)}>
			<PageTitle>{t('Добавление площадки')}</PageTitle>

			<CreateSourceForm className={styles.form} />
		</Page>
	);
};

export default CreateSource;
